                   "cause": "fire", "damages": [{"itemType": "sword", "amount": 200}]}}]}
                """));
    }

    @Test
    void anUnknownOperationIsRejected() {
        assertThrows(ClaimOfficeException.class, () -> run("""
                {"customer": {"yearsWithMHPCO": 0}, "steps": [{"op": "renew"}]}
                """));
    }
}
