        assertEquals("", result.stdout());
        assertTrue(result.stderr().contains("amulet"), result.stderr());
    }

    @Test
    void malformedJsonFailsWithoutWritingResults() {
        Result result = invoke("{ not json");
        assertNotEquals(0, result.status());
        assertEquals("", result.stdout());
    }
}
