                   {"op": "claim", "policy": 0, "incident": {
                     "cause": "fire", "damages": [{"itemType": "sword", "amount": -200}]}}]}
                """);
        assertNotEquals(0, result.status());
        assertEquals("", result.stdout());
        assertTrue(result.stderr().contains("-200"), result.stderr());
    }

